import{_ as r,o as i,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const h=JSON.parse('{"title":"第 3 章 Profilling","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/Profilling.md","filePath":"fundamentals/Profilling.md"}'),o={name:"fundamentals/Profilling.md"};function e(t,l,s,f,g,p){return i(),n("div",null,[...l[0]||(l[0]=[a('<h1 id="第-3-章-profilling" tabindex="-1"><strong>第 3 章 Profilling</strong> <a class="header-anchor" href="#第-3-章-profilling" aria-label="Permalink to &quot;**第 3 章 Profilling**&quot;">​</a></h1><h2 id="_1-benchmark和profilling的关系" tabindex="-1">1. Benchmark和Profilling的关系 <a class="header-anchor" href="#_1-benchmark和profilling的关系" aria-label="Permalink to &quot;1. Benchmark和Profilling的关系&quot;">​</a></h2><p>Benchmark：描述的是请求侧的表现，可以把 benchmark 看成黑盒测量</p><p>profilling：Profiling 则记录程序内部的执行，CPU 在运行哪些 operator、GPU 执行了哪些 kernel、时间花在哪里，可以把profiling 看成打开内部过程的白盒观察。</p><p>两者要配合：先用指标明确问题，再用内部记录检验原因，修改后回到 benchmark 看结果。</p><h2 id="_2-profilling" tabindex="-1">2. Profilling <a class="header-anchor" href="#_2-profilling" aria-label="Permalink to &quot;2. Profilling&quot;">​</a></h2><p>值得关注的其实就是三件事情：<strong>耗时长的事件、频繁重复的事件、事件之间的空隙</strong>。</p><p><strong>明确症状 → 提出假设 → 用 trace 检查 → 修改并验证</strong>：</p><ol><li><strong>明确症状。</strong> 固定模型、硬件、版本、输入输出长度和并发，看慢的是 TTFT、TPOT，还是吞吐；先排除负载变化造成的差异。</li><li><strong>提出可以检查的假设。</strong><ol><li>TTFT 高，就检查排队和 prefill；</li><li>TPOT 抖，就检查 decode 是否被 prefill 插入或其他工作阻塞；</li><li>吞吐上不去，就检查实际 batch、并发和计算 / 通信等待。</li><li>指标决定从哪里查，但本身不是原因的证明</li></ol></li><li><strong>验证假设和改动。</strong> 在相同 rank、相同执行阶段采集短 trace，把可疑事件对应到代码。每次集中改一个问题，确认目标开销减少，再关闭 profiler，重复跑同条件 benchmark，并补正确性检查。</li></ol>',9)])])}const d=r(o,[["render",e]]);export{h as __pageData,d as default};
